9	/// Loader for local templates (user and project).
10	#[derive(Debug, Clone)]
11	pub struct LocalLoader {
12	    templates: HashMap<String, (Template, TemplateSource)>,
13	}
14	
15	impl LocalLoader {
16	    /// Load templates from user and project directories.
17	    pub fn new(project_root: Option<&Path>) -> Result<Self> {
18	        let mut templates = HashMap::new();
19	
20	        // Load user templates (~/.bivvy/templates/)
21	        if let Some(user_dir) = Self::user_templates_dir() {
22	            Self::load_from_dir(&user_dir, TemplateSource::User, &mut templates)?;
23	        }
24	
25	        // Load project templates (.bivvy/templates/)
26	        if let Some(root) = project_root {
27	            let project_dir = root.join(".bivvy").join("templates");
28	            Self::load_from_dir(&project_dir, TemplateSource::Project, &mut templates)?;
29	        }
30	
31	        Ok(Self { templates })
32	    }
33	
34	    /// Get user templates directory.
35	    fn user_templates_dir() -> Option<PathBuf> {
36	        crate::sys::home_dir().map(|h| h.join(".bivvy").join("templates"))
37	    }
38	
39	    /// Load templates from a directory (recursively).
40	    fn load_from_dir(
41	        dir: &Path,
42	        source: TemplateSource,
43	        templates: &mut HashMap<String, (Template, TemplateSource)>,
44	    ) -> Result<()> {
45	        if !dir.exists() {
46	            return Ok(());
47	        }
48	
49	        // Load from steps/ subdirectory
50	        let steps_dir = dir.join("steps");
51	        if steps_dir.exists() {
52	            Self::load_templates_recursive(&steps_dir, source, templates)?;
53	        }
54	
55	        Ok(())
56	    }
57	
58	    fn load_templates_recursive(
59	        dir: &Path,
60	        source: TemplateSource,
61	        templates: &mut HashMap<String, (Template, TemplateSource)>,
62	    ) -> Result<()> {
63	        if !dir.is_dir() {
64	            return Ok(());
65	        }
66	
67	        for entry in fs::read_dir(dir)? {
68	            let entry = entry?;
69	            let path = entry.path();
70	
71	            if path.is_dir() {
72	                Self::load_templates_recursive(&path, source, templates)?;
73	            } else if path
74	                .extension()
75	                .map(|e| e == "yml" || e == "yaml")
76	                .unwrap_or(false)
77	            {
78	                let content = fs::read_to_string(&path)?;
79	                let template: Template = serde_yaml::from_str(&content).map_err(|e| {
80	                    crate::error::BivvyError::ConfigParseError {
81	                        path: path.clone(),
82	                        message: e.to_string(),
83	                    }
84	                })?;
85	
86	                // Project templates override user templates
87	                let key = format!("{}/{}", template.category, template.name);
88	                if source == TemplateSource::Project || !templates.contains_key(&key) {
89	                    templates.insert(key, (template, source));
90	                }
91	            }
92	        }
93	
94	        Ok(())
95	    }
96	
97	    /// Get a template by name (unqualified — returns first match).
98	    pub fn get(&self, name: &str) -> Option<&Template> {
99	        // Try as qualified key first
100	        if let Some((t, _)) = self.templates.get(name) {
101	            return Some(t);
102	        }
103	        // Fall back to unqualified name match
104	        self.templates
105	            .values()
106	            .find(|(t, _)| t.name == name)
107	            .map(|(t, _)| t)
108	    }
109	
110	    /// Get a template with its source (unqualified — returns first match).
111	    pub fn get_with_source(&self, name: &str) -> Option<(&Template, TemplateSource)> {
112	        // Try as qualified key first
113	        if let Some((t, s)) = self.templates.get(name) {
114	            return Some((t, *s));
115	        }
116	        // Fall back to unqualified name match
117	        self.templates
118	            .values()
119	            .find(|(t, _)| t.name == name)
120	            .map(|(t, s)| (t, *s))
121	    }
122	
123	    /// Get a template with its source, filtering by category.
124	    pub fn get_with_source_by_category(
125	        &self,
126	        name: &str,
127	        category: &str,
128	    ) -> Option<(&Template, TemplateSource)> {
129	        let key = format!("{}/{}", category, name);
130	        self.templates.get(&key).map(|(t, s)| (t, *s))
131	    }
132	
133	    /// Get all template names (qualified as `category/name`).
134	    pub fn template_names(&self) -> Vec<&str> {
135	        self.templates.keys().map(|s| s.as_str()).collect()
136	    }
137	
138	    /// Check if a template exists (by unqualified name).
139	    pub fn has(&self, name: &str) -> bool {
140	        self.templates.contains_key(name) || self.templates.values().any(|(t, _)| t.name == name)
141	    }
142	}
