/// Fill a buffer with cryptographically secure random bytes.
#[cfg(unix)]
pub fn random_bytes(buf: &mut [u8]) {
    use std::io::Read;
    std::fs::File::open("/dev/urandom")
        .and_then(|mut f| f.read_exact(buf))
