        for i in 0..3 {
            let path = dir
                .path()
                .join(format!("2026-04-{:02}T00-00-00_{}.jsonl", i + 1, i));
            fs::write(&path, &data).unwrap();
            // Small delay to ensure different mtimes
            std::thread::sleep(std::time::Duration::from_millis(10));
