    let metadata = StagedUpdate {
        version: info.latest.clone(),
        staged_at: Utc::now(),
    };
    let meta_path = dir.join("metadata.json");
    fs::write(meta_path, serde_json::to_string_pretty(&metadata)?)?;

    Ok(())
}

