120	///
121	/// Only requires `OutputWriter` — displays confirmation messages but does not prompt.
122	fn set_auto_update(ui: &mut dyn OutputWriter, enabled: bool) -> Result<CommandResult> {
123	    let home = crate::sys::home_dir().ok_or_else(|| {
124	        crate::error::BivvyError::Other(anyhow::anyhow!("Could not determine home directory"))
125	    })?;
126	
127	    let config_dir = home.join(".bivvy");
128	    let config_path = config_dir.join("config.yml");
129	
130	    // Read existing config or start fresh
