120	// === URL percent-encoding ===
121	
122	/// Percent-encode a string for use in URLs.
123	///
124	/// Encodes all characters except unreserved characters
125	/// (A-Z, a-z, 0-9, `-`, `_`, `.`, `~`) as defined in RFC 3986.
126	pub fn percent_encode(input: &str) -> String {
127	    let mut encoded = String::with_capacity(input.len());
128	    for byte in input.bytes() {
129	        match byte {
130	            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
131	                encoded.push(byte as char);
132	            }
133	            _ => {
134	                encoded.push('%');
135	                encoded.push(HEX_CHARS[(byte >> 4) as usize] as char);
136	                encoded.push(HEX_CHARS[(byte & 0x0F) as usize] as char);
137	            }
138	        }
139	    }
140	    encoded
141	}
142	
143	const HEX_CHARS: &[u8; 16] = b"0123456789ABCDEF";
144	
145	/// Decode a percent-encoded string.
146	pub fn percent_decode(input: &str) -> Result<String, std::string::FromUtf8Error> {
147	    let mut bytes = Vec::with_capacity(input.len());
148	    let mut chars = input.bytes();
149	    while let Some(b) = chars.next() {
150	        if b == b'%' {
151	            let hi = chars.next().and_then(from_hex_digit);
152	            let lo = chars.next().and_then(from_hex_digit);
153	            match (hi, lo) {
154	                (Some(h), Some(l)) => bytes.push((h << 4) | l),
155	                _ => {
156	                    // Malformed percent encoding — pass through literally
157	                    bytes.push(b'%');
158	                }
159	            }
160	        } else if b == b'+' {
161	            bytes.push(b' ');
162	        } else {
163	            bytes.push(b);
164	        }
165	    }
166	    String::from_utf8(bytes)
167	}
168	
169	fn from_hex_digit(b: u8) -> Option<u8> {
170	    match b {
171	        b'0'..=b'9' => Some(b - b'0'),
172	        b'a'..=b'f' => Some(b - b'a' + 10),
173	        b'A'..=b'F' => Some(b - b'A' + 10),
174	        _ => None,
175	    }
176	}
