178	// === Browser/URL opening ===
179	
180	/// Open a URL in the platform's default browser or handler.
181	pub fn open_in_browser(url: &str) -> std::io::Result<()> {
182	    let (cmd, args): (&str, &[&str]) = if cfg!(target_os = "macos") {
183	        ("open", &[url])
184	    } else if cfg!(windows) {
185	        ("cmd", &["/C", "start", "", url])
186	    } else {
187	        ("xdg-open", &[url])
188	    };
189	
190	    std::process::Command::new(cmd)
191	        .args(args)
192	        .stdin(std::process::Stdio::null())
193	        .stdout(std::process::Stdio::null())
194	        .stderr(std::process::Stdio::null())
195	        .status()
196	        .map(|_| ())
197	}
