200	
201	/// Check whether an executable exists on the system PATH.
202	pub fn find_on_path(binary: &str) -> Option<PathBuf> {
203	    let path_var = std::env::var_os("PATH")?;
204	    let separator = if cfg!(windows) { ';' } else { ':' };
205	
206	    for dir in path_var.to_string_lossy().split(separator) {
207	        let candidate = Path::new(dir).join(binary);
208	        if candidate.is_file() {
209	            return Some(candidate);
210	        }
211	        // On Windows, also check with common extensions
212	        if cfg!(windows) {
213	            for ext in &[".exe", ".cmd", ".bat", ".com"] {
214	                let with_ext = Path::new(dir).join(format!("{}{}", binary, ext));
215	                if with_ext.is_file() {
216	                    return Some(with_ext);
217	                }
218	            }
219	        }
220	    }
221	    None
222	}
