226	/// Fill a buffer with cryptographically secure random bytes.
227	#[cfg(unix)]
228	pub fn random_bytes(buf: &mut [u8]) {
229	    use std::io::Read;
230	    std::fs::File::open("/dev/urandom")
231	        .and_then(|mut f| f.read_exact(buf))
232	        .expect("Failed to read /dev/urandom");
233	}
