235	/// Fill a buffer with cryptographically secure random bytes.
236	#[cfg(windows)]
237	pub fn random_bytes(buf: &mut [u8]) {
238	    extern "system" {
239	        fn BCryptGenRandom(
240	            hAlgorithm: *mut std::ffi::c_void,
241	            pbBuffer: *mut u8,
242	            cbBuffer: u32,
243	            dwFlags: u32,
244	        ) -> i32;
245	    }
246	    const BCRYPT_USE_SYSTEM_PREFERRED_RNG: u32 = 0x00000002;
247	    let status = unsafe {
248	        BCryptGenRandom(
249	            std::ptr::null_mut(),
250	            buf.as_mut_ptr(),
251	            buf.len() as u32,
252	            BCRYPT_USE_SYSTEM_PREFERRED_RNG,
253	        )
254	    };
255	    assert!(status >= 0, "BCryptGenRandom failed with status {status}");
256	}
