258	// === Glob pattern matching ===
259	
260	/// Match files against a glob pattern and return matching paths.
261	///
262	/// Supports `*` (any non-separator chars), `**` (recursive directory match),
263	/// and `?` (single char). The pattern should be an absolute path with glob
264	/// characters (e.g., `/path/to/project/*.rb`).
265	pub fn glob(pattern: &str) -> Result<Vec<PathBuf>, String> {
266	    let pattern = pattern.replace('\\', "/");
267	
268	    // Find where the first wildcard character appears
269	    let first_wild = pattern.find(['*', '?', '[']).unwrap_or(pattern.len());
270	
271	    // Base directory is everything up to the last '/' before the first wildcard
272	    let base_end = pattern[..first_wild].rfind('/').map(|i| i + 1).unwrap_or(0);
273	    let base_dir = if base_end > 0 {
274	        PathBuf::from(&pattern[..base_end])
275	    } else {
276	        PathBuf::from(".")
277	    };
278	
279	    if !base_dir.exists() {
280	        return Ok(Vec::new());
281	    }
282	
283	    let rel_pattern = &pattern[base_end..];
284	
285	    // Walk the directory tree and collect all files
286	    let mut all_paths = Vec::new();
287	    walk_dir_recursive(&base_dir, &mut all_paths);
288	
289	    // Match each path against the relative pattern
290	    let mut matches: Vec<PathBuf> = Vec::new();
291	    for path in all_paths {
292	        let rel_path = path
293	            .strip_prefix(&base_dir)
294	            .unwrap_or(&path)
295	            .to_string_lossy()
296	            .replace('\\', "/");
297	
298	        if glob_match_path(rel_pattern, &rel_path) {
299	            matches.push(path);
300	        }
301	    }
302	
303	    matches.sort();
304	    Ok(matches)
305	}
306	
307	fn walk_dir_recursive(dir: &Path, results: &mut Vec<PathBuf>) {
308	    let entries = match std::fs::read_dir(dir) {
309	        Ok(e) => e,
310	        Err(_) => return,
311	    };
312	    for entry in entries.flatten() {
313	        let path = entry.path();
314	        results.push(path.clone());
315	        if path.is_dir() {
316	            walk_dir_recursive(&path, results);
317	        }
318	    }
319	}
320	
321	/// Match a glob pattern against a path string.
322	///
323	/// Both pattern and path use `/` as separator. The pattern may contain
324	/// `*` (matches non-separator chars), `**` (matches across separators),
325	/// and `?` (matches single non-separator char).
326	fn glob_match_path(pattern: &str, path: &str) -> bool {
327	    let pat_parts: Vec<&str> = pattern.split('/').collect();
328	    let path_parts: Vec<&str> = path.split('/').collect();
329	    match_components(&pat_parts, &path_parts)
330	}
331	
332	fn match_components(patterns: &[&str], paths: &[&str]) -> bool {
333	    if patterns.is_empty() {
334	        return paths.is_empty();
335	    }
336	
337	    if patterns[0] == "**" {
338	        // `**` matches zero or more path components
339	        for i in 0..=paths.len() {
340	            if match_components(&patterns[1..], &paths[i..]) {
341	                return true;
342	            }
343	        }
344	        return false;
345	    }
346	
347	    if paths.is_empty() {
348	        return false;
349	    }
350	
351	    // Match first component, then recurse
352	    match_segment(patterns[0], paths[0]) && match_components(&patterns[1..], &paths[1..])
353	}
354	
355	/// Match a single path segment against a glob pattern segment.
356	///
357	/// Handles `*` (any chars) and `?` (single char).
358	fn match_segment(pattern: &str, text: &str) -> bool {
359	    match_bytes(pattern.as_bytes(), text.as_bytes())
360	}
361	
362	fn match_bytes(pattern: &[u8], text: &[u8]) -> bool {
363	    match (pattern.first(), text.first()) {
364	        (None, None) => true,
365	        (Some(b'*'), _) => {
366	            // Try matching zero chars, or advance text by one
367	            match_bytes(&pattern[1..], text)
368	                || (!text.is_empty() && match_bytes(pattern, &text[1..]))
369	        }
370	        (Some(b'?'), Some(_)) => match_bytes(&pattern[1..], &text[1..]),
371	        (Some(&a), Some(&b)) if a == b => match_bytes(&pattern[1..], &text[1..]),
372	        _ => false,
373	    }
374	}
